import{_ as t,o as s,c as e,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 19 章 自动化工作流的可靠性","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 19 章 自动化工作流的可靠性.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 19 章 自动化工作流的可靠性.md"}'),i={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 19 章 自动化工作流的可靠性.md"};function l(o,a,p,d,r,h){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="第-19-章-自动化工作流的可靠性" tabindex="-1">第 19 章 自动化工作流的可靠性 <a class="header-anchor" href="#第-19-章-自动化工作流的可靠性" aria-label="Permalink to &quot;第 19 章 自动化工作流的可靠性&quot;">​</a></h1><h2 id="_19-1-自动化最大的敌人-悄悄出错" tabindex="-1">19.1 自动化最大的敌人：悄悄出错 <a class="header-anchor" href="#_19-1-自动化最大的敌人-悄悄出错" aria-label="Permalink to &quot;19.1 自动化最大的敌人：悄悄出错&quot;">​</a></h2><p>自动化最危险的不是&quot;跑不起来&quot;，而是**&quot;看起来在跑，其实错了&quot;**。一份错数据的周报，比没有周报更有害——因为没人会怀疑它。</p><p>所以这一章只讲一件事：<strong>怎么让自动化稳定、可信、可追责。</strong></p><h2 id="_19-2-可靠性三支柱" tabindex="-1">19.2 可靠性三支柱 <a class="header-anchor" href="#_19-2-可靠性三支柱" aria-label="Permalink to &quot;19.2 可靠性三支柱&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>留痕（Logging）→ 每次运行都有记录</span></span>
<span class="line"><span>验证（Validation）→ 产出自动校验</span></span>
<span class="line"><span>人审（Human-in-the-loop）→ 关键节点人把关</span></span></code></pre></div><p>缺一个，可靠性就塌一角。</p><h2 id="_19-3-支柱一-留痕" tabindex="-1">19.3 支柱一：留痕 <a class="header-anchor" href="#_19-3-支柱一-留痕" aria-label="Permalink to &quot;19.3 支柱一：留痕&quot;">​</a></h2><p>每次运行，自动记录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间、输入（文件/参数）、步骤、关键中间值、输出、耗时</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运行日志示例：</span></span>
<span class="line"><span>2026-08-08 18:00:01 开始：合并 3 个 CSV</span></span>
<span class="line"><span>2026-08-08 18:00:03 读取 data/a.csv（1,204 行）</span></span>
<span class="line"><span>2026-08-08 18:00:05 合并完成，共 3,612 行</span></span>
<span class="line"><span>2026-08-08 18:00:06 校验：行数一致 ✓，写入 output/</span></span></code></pre></div><p>出问题时，日志就是案发现场。</p><h2 id="_19-4-支柱二-验证" tabindex="-1">19.4 支柱二：验证 <a class="header-anchor" href="#_19-4-支柱二-验证" aria-label="Permalink to &quot;19.4 支柱二：验证&quot;">​</a></h2><p>自动化内部要自带&quot;体检&quot;，不能交付前才发现：</p><table tabindex="0"><thead><tr><th>检查</th><th>示例</th></tr></thead><tbody><tr><td>数量校验</td><td>输出行数 = 输入行数之和</td></tr><tr><td>格式校验</td><td>日期格式、字段齐全</td></tr><tr><td>内容校验</td><td>关键字段无空值、无重复</td></tr><tr><td>阈值告警</td><td>环比变化 &gt; 50% 时标记异常</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>例：合并后自动校验&quot;行数 = 1,204 + 1,158 + 1,250 = 3,612&quot;，不通过就报警，不静默通过。</span></span></code></pre></div><h2 id="_19-5-支柱三-人审节点" tabindex="-1">19.5 支柱三：人审节点 <a class="header-anchor" href="#_19-5-支柱三-人审节点" aria-label="Permalink to &quot;19.5 支柱三：人审节点&quot;">​</a></h2><p>自动化跑得再稳，<strong>最后一公里永远留给人类</strong>：</p><ul><li>重要输出：生成草稿 → 人确认 → 才发布；</li><li>不可逆操作：先模拟 → 人批准 → 才执行；</li><li>异常处理：自动失败自动暂停，等人决策，不自动重试掩盖问题。</li></ul><h2 id="_19-6-处理失败的正确姿势" tabindex="-1">19.6 处理失败的正确姿势 <a class="header-anchor" href="#_19-6-处理失败的正确姿势" aria-label="Permalink to &quot;19.6 处理失败的正确姿势&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>失败 → 停下（不硬跑）→ 记录现场 → 通知人 → 人决策：</span></span>
<span class="line"><span>      修输入重跑 / 修步骤 / 放弃本次</span></span></code></pre></div><p><strong>不要</strong>：失败后自动重试 10 次掩盖问题。</p><h2 id="_19-7-可靠性的进阶-幂等与可恢复" tabindex="-1">19.7 可靠性的进阶：幂等与可恢复 <a class="header-anchor" href="#_19-7-可靠性的进阶-幂等与可恢复" aria-label="Permalink to &quot;19.7 可靠性的进阶：幂等与可恢复&quot;">​</a></h2><ul><li><strong>幂等</strong>：同一输入跑两次，结果一样（不会重复发消息、重复扣款）；</li><li><strong>可恢复</strong>：第 3 步失败，修好后从第 3 步继续，而不是从头再来；</li><li><strong>可回退</strong>：本次输出错了，能一键回到上一次正确版本。</li></ul><h2 id="_19-8-练习" tabindex="-1">19.8 练习 <a class="header-anchor" href="#_19-8-练习" aria-label="Permalink to &quot;19.8 练习&quot;">​</a></h2><ol><li>找一个你现有的自动化任务，检查它是否三支柱齐全；</li><li>补上日志和校验（至少数量校验）；</li><li>模拟一次失败，确认它会&quot;停下 + 通知人&quot;而不是&quot;静默出错&quot;。</li></ol><blockquote><p>小结：可靠的自动化 = <strong>看得见（留痕）+ 验得出（校验）+ 人把关（人审）</strong>。宁可慢一点，不可错得漂亮。</p></blockquote>`,27)])])}const b=t(i,[["render",l]]);export{u as __pageData,b as default};
